  const $=s=>panel.querySelector(s),table=$('#inventoryViewTable'),thead=table.querySelector('thead'),tbody=table.querySelector('tbody'),empty=$('#inventoryViewEmpty'),meta=$('#inventoryViewMeta'),presetSelect=$('#inventoryPresetSelect'),search=$('#inventoryViewSearch'),columnsPanel=$('#inventoryColumnPanel'),columnGrid=$('#inventoryColumnGrid'),filters=$('#inventoryReviewFilters'),activeFilters=$('#inventoryActiveFilters'),mappingStatus=$('#inventoryMappingStatus'),sourceClassification=$('#inventorySourceClassification'),reviewReason=$('#inventoryReviewReason'),selectionBar=$('#inventorySelectionBar'),drawer=$('#inventoryReviewDrawer'),detailsButton=$('#inventoryDetails'),askAI=$('#inventoryAskAI'),deepReview=$('#inventoryDeepReview'),copySelected=$('#inventoryCopySelected'),fillToggle=$('#inventoryFillToggle'),fillMenu=$('#inventoryFillMenu'),clearFill=$('#inventoryClearFill'),focusToggle=$('#inventoryFocusToggle'),densityToggle=$('#inventoryDensityToggle'),dateFormatSelect=$('#inventoryDateFormat');

  function readableToken(value){return String(value??'').trim().replace(/[_-]+/g,' ').replace(/\s+/g,' ').toLowerCase().replace(/(^|[\s/])\p{L}/gu,m=>m.toUpperCase())}
  function categoryLabel(value){const key=String(value??'').trim().toUpperCase();const known={CONTINUITY_EXACT_NAME_PRICE_SAME:'Continuity: exact name, same price',CONTINUITY_EXACT_NAME_PRICE_CHANGED:'Continuity: exact name, price changed',MULTIPLE_SOURCE_CODES:'Multiple CMS codes in source',CMS_DISCONTINUED:'CMS item discontinued; local item retained',CODE_NAME_MISMATCH:'CMS code/name mismatch',UNMAPPED:'No CMS mapping found',NEW_UNMAPPED:'New item without CMS mapping',MISSING_SOURCE_CMS_NAME:'Source CMS name is missing',MULTIPLE_SOURCE_CMS_NAMES:'Multiple source CMS names',RECYCLED_CODE:'CMS code appears recycled'};return known[key]||readableToken(key)||'Review evidence'}
  function reasonEvidence(value){if(value===null||value===undefined||value==='')return {summary:'—',details:[]};if(typeof value!=='string')return {summary:String(value),details:[]};const raw=value.trim();if(!(raw.startsWith('{')&&raw.endsWith('}')))return {summary:raw,details:[]};try{const parsed=JSON.parse(raw);if(!parsed||Array.isArray(parsed)||typeof parsed!=='object')return {summary:raw,details:[]};const category=parsed.category??parsed.reason_code??parsed.code;const preferred=parsed.message??parsed.reason??parsed.summary??parsed.detail;const summary=preferred?String(preferred):categoryLabel(category);const details=[];if(category)details.push(['Category',categoryLabel(category)]);Object.entries(parsed).forEach(([key,val])=>{if(['category','reason_code','code','message','reason','summary','detail'].includes(key)||val===null||val===undefined||val==='')return;const text=typeof val==='object'?(Array.isArray(val)?val.join(', '):Object.entries(val).map(([k,v])=>`${readableToken(k)}: ${v}`).join(' · ')):String(val);details.push([readableToken(key),text])});return {summary,details}}catch{return {summary:raw,details:[]}}}
  function formatDate(value){const raw=String(value??'');const match=/^(\d{4})-(\d{2})-(\d{2})$/.exec(raw);if(!match)return raw;const [,year,month,day]=match;if(state.dateFormat==='mm-dd-yyyy')return `${month}-${day}-${year}`;if(state.dateFormat==='yyyy-mm-dd')return `${year}-${month}-${day}`;if(state.dateFormat==='dd-mmm-yyyy'){const names=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];return `${day}-${names[Number(month)-1]||month}-${year}`}return `${day}-${month}-${year}`}
  function format(value,def,field){if(field==='review_reason')return reasonEvidence(value).summary;if(value===null||value===undefined||value==='')return '—';if(def?.data_type==='decimal'){const n=Number(value);return Number.isFinite(n)?n.toLocaleString(undefined,{maximumFractionDigits:3}):String(value)}if(def?.data_type==='date')return formatDate(value);return String(value)}
  function cellClass(field,value){if(field==='mapping_status'||field==='source_classification')return ` inventory-status-cell status-${String(value||'none').toLowerCase().replace(/[^a-z0-9]+/g,'-')}`;if(field.endsWith('_qty')||field.includes('price'))return ' inventory-number-cell';return ''}
  function rowClass(item){const values=[item.source_classification,item.mapping_status].filter(Boolean).map(String);if(values.includes('CONFLICT')||values.includes('RECYCLED_CODE'))return 'inventory-row-critical';if(values.includes('REVIEW')||values.includes('REVIEW_REQUIRED')||values.includes('CMS_DISCONTINUED')||values.includes('NEW_UNMAPPED')||values.includes('UNMAPPED'))return 'inventory-row-review';return ''}
  const clampedWidth=value=>Math.max(72,Math.min(520,Number(value)||120));
  const columnWidth=col=>state.columnWidths[col.field]?clampedWidth(state.columnWidths[col.field]):(col.width?clampedWidth(col.width):null);
  function sortLabel(){return state.columnsRendered.find(col=>col.field===state.sortField)?.label||state.registry.find(field=>field.key===state.sortField)?.label||readableToken(state.sortField)}
  function renderColumns(columns){thead.innerHTML=`<tr><th class="inventory-row-header inventory-frozen-select"><button id="inventorySelectVisible" type="button" aria-label="Select visible rows" title="Select visible rows" aria-pressed="false"><svg aria-hidden="true" width="18" height="18" viewBox="0 0 18 18" fill="none"><rect x="3" y="3" width="12" height="12" rx="1.5" stroke="currentColor" stroke-width="1.5"/><path d="M6 6h6v6H6z" fill="currentColor" opacity=".28"/></svg></button></th>${columns.map((col,index)=>{const width=columnWidth(col),active=state.sortField===col.field,ariaSort=active?(state.sortDir==='desc'?'descending':'ascending'):'none',indicator=active?(state.sortDir==='desc'?'▼':'▲'):'↕',label=esc(col.label);const content=col.sortable?`<button class="inventory-sort-button ${active?'is-active':''}" type="button" data-sort-field="${esc(col.field)}" aria-label="Sort by ${label}${active?` ${ariaSort}`:''}"><span class="inventory-sort-label">${label}</span><span class="inventory-sort-indicator" aria-hidden="true">${indicator}</span></button>`:label;return `<th data-field="${esc(col.field)}" class="${index===0?'inventory-frozen-first':''}" aria-sort="${ariaSort}" style="${width?`width:${width}px;min-width:${width}px;max-width:${width}px`:''}">${content}</th>`}).join('')}</tr>`}
  function selectedIndices(){const result=[];state.items.forEach((item,index)=>{if(state.selected.has(rowKey(item,index)))result.push(index)});return result}
  function normalizedRange(a,b){if(!a||!b)return null;return {r1:Math.min(a.row,b.row),r2:Math.max(a.row,b.row),c1:Math.min(a.col,b.col),c2:Math.max(a.col,b.col)}}
  function cellSelectionCount(){const r=state.cellRange;return r?(r.r2-r.r1+1)*(r.c2-r.c1+1):0}
  function isCellSelected(row,col){const r=state.cellRange;return Boolean(r&&row>=r.r1&&row<=r.r2&&col>=r.c1&&col<=r.c2)}
  const FILL_TOKENS=new Set(['yellow','green','red','blue','orange','gray']);
  function cellFormatKey(row,col){const item=state.items[row],column=state.columnsRendered[col];if(!item||!column)return null;return `${rowKey(item,row)}\u0000${column.field}`}
